#!/usr/bin/env python3
"""灵巧手手势交互终端：输入手势名 → 机械手执行"""
import rclpy
from rclpy.node import Node
from dex_hand_ros2.msg import GestureCmd


class GestureCLI(Node):
    def __init__(self):
        super().__init__("gesture_cli")
        self.publisher = self.create_publisher(GestureCmd, "/dex_hand/gesture_cmd", 10)

    def send_gesture(self, name: str, speed: float):
        msg = GestureCmd()
        msg.gesture = name
        msg.speed = speed
        self.publisher.publish(msg)
        self.get_logger().info(f"发送手势: {name}, 速度: {speed}")


def main():
    rclpy.init()
    cli = GestureCLI()

    print("=" * 50)
    print("  灵巧手手势控制终端")
    print("  预定义手势: open | fist | vgesture")
    print("  输入 'list' 查看全部手势")
    print("  输入 'demo' 启动演示模式")
    print("  输入 'quit' 退出")
    print("=" * 50)

    try:
        while rclpy.ok():
            user_input = input("\n手势名> ").strip()
            if not user_input:
                continue

            if user_input.lower() == "quit":
                print("退出.")
                break
            elif user_input.lower() == "list":
                print("  预定义: open, fist, vgesture")
                print("  (自定义手势通过 /dex_hand/add_gesture 服务注册)")
            elif user_input.lower() == "demo":
                print("  请在新终端运行: ros2 service call /dex_hand/demo_gestures std_srvs/srv/Trigger {}")
            else:
                speed = 1.0
                cli.send_gesture(user_input, speed)
    except KeyboardInterrupt:
        print("\n中断.")
    finally:
        cli.destroy_node()
        rclpy.shutdown()


if __name__ == "__main__":
    main()
